function check(value,message){if(!value)throw Error(message);}
const first=new AppleScript("on rootValue()
return current date
end rootValue
on nestedValue()
set stamp to current date
return {stamp, {nested:stamp, text:"2020-01-02T03:04:05Z", appleScriptDatePaths:{"ordinary"}, value:7}}
end nestedValue
on failValue()
error "Neutral AppleScript failure" number 7
end failValue
on recoverValue()
return "Recovered café 🐼"
end recoverValue"),second=AppleScript.create("on rootValue()
return current date
end rootValue
on nestedValue()
set stamp to current date
return {stamp, {nested:stamp, text:"2020-01-02T03:04:05Z", appleScriptDatePaths:{"ordinary"}, value:7}}
end nestedValue
on failValue()
error "Neutral AppleScript failure" number 7
end failValue
on recoverValue()
return "Recovered café 🐼"
end recoverValue");
check(first.lastError===undefined&&first.lastResult===undefined,'initial fields');
const before=Date.now();
check(first.execute('rootValue',[])&&first.lastResult instanceof Date,'root date');
check(first.lastResult.getTime()>=before-2000&&first.lastResult.getTime()<=Date.now()+1000,'native date instant');
check(first.execute('nestedValue',[]),'nested execution');
const values=first.lastResult;
check(values[0] instanceof Date&&values[1].nested instanceof Date,'nested dates');
check(values[0].getTime()===values[1].nested.getTime(),'same native instant');
check(values[1].text==='2020-01-02T03:04:05Z'&&typeof values[1].text==='string','date-like text');
check(values[1].value===7&&values[1].appleScriptDatePaths[0]==='ordinary','ordinary record keys');
check(second.lastResult===undefined,'independent values');
check(second.execute('failValue',[])===false&&second.lastError.includes('Neutral AppleScript failure'),'ordinary failure');
check(second.execute('recoverValue',[])&&second.lastError===undefined&&second.lastResult==='Recovered café 🐼','recovery');
check(context.appleScriptResponses[0] instanceof Date&&context.appleScriptResponses[1]===values,'response collection dates');
console.log('Native AppleScript dates, values and recovery passed café 🐼');

on execute(payload)
return {stamp:current date, text:"Neutral café 🐼"}
end execute
